WITH Src AS (SELECT * FROM departments WHERE location NOT IN ('Berlin', 'London') AND location <> 'Singapore' AND location NOT IN ('Chiang Mai', 'New York', 'Singapore')), agg AS (SELECT CASE WHEN dept_name IN ('Engineering', 'Finance') THEN 'core' ELSE 'other' END AS dept_name_group, SUM(budget) AS total_budget FROM Src GROUP BY CASE WHEN dept_name IN ('Engineering', 'Finance') THEN 'core' ELSE 'other' END) SELECT * FROM agg WHERE total_budget >= 8217000 ORDER BY total_budget DESC
